using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using System.Runtime.Loader;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using Emby.Server.Implementations.Plugins;
using MediaBrowser.Model.Plugins;

namespace Emby.Server.Implementations.Tests.Plugins
{
    public class PluginManagerTests
    {
        private class TestPluginLoadContext : AssemblyLoadContext
        {
            private readonly Exception _exceptionToThrow;
            private readonly string _path;

            public TestPluginLoadContext(string path, Exception exceptionToThrow = null)
            {
                _path = path;
                _exceptionToThrow = exceptionToThrow;
            }

            protected override Assembly Load(AssemblyName assemblyName)
            {
                return null;
            }

            public override Assembly LoadFromAssemblyPath(string assemblyPath)
            {
                if (_exceptionToThrow != null)
                {
                    throw _exceptionToThrow;
                }
                // Return a dummy assembly for testing
                return Assembly.GetExecutingAssembly();
            }
        }

        private class TestPlugin : LocalPlugin
        {
            public TestPlugin(string path, List<string> dllFiles, bool isEnabledAndSupported)
            {
                Path = path;
                DllFiles = dllFiles;
                IsEnabledAndSupported = isEnabledAndSupported;
                Manifest = new PluginManifest { Status = PluginStatus.Enabled };
                Version = new Version(1, 0, 0);
                Name = "TestPlugin";
            }

            public override string Path { get; }
            public override List<string> DllFiles { get; }
            public override bool IsEnabledAndSupported { get; }
            public override PluginManifest Manifest { get; }
            public override Version Version { get; }
            public override string Name { get; }
        }

        [Fact]
        public void LoadAssemblies_LogsErrorOnFileLoadException()
        {
            var loggerMock = new Mock<ILogger<PluginManager>>();
            var appHostMock = new Mock<IServerApplicationHost>();
            var config = new ServerConfiguration();
            var pluginsPath = Path.GetTempPath();
            var appVersion = new Version(1, 0, 0);

            var pluginManager = new PluginManager(loggerMock.Object, appHostMock.Object, config, pluginsPath, appVersion);

            // Create a plugin that will throw FileLoadException on LoadFromAssemblyPath
            var plugin = new TestPlugin("testpath", new List<string> { "bad.dll" }, true);

            // Inject the plugin into the private _plugins list via reflection
            var pluginsField = typeof(PluginManager).GetField("_plugins", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            pluginsField.SetValue(pluginManager, new List<LocalPlugin> { plugin });

            // Replace PluginLoadContext with our TestPluginLoadContext that throws FileLoadException
            var assemblyLoadContextsField = typeof(PluginManager).GetField("_assemblyLoadContexts", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            assemblyLoadContextsField.SetValue(pluginManager, new List<AssemblyLoadContext>());

            // We cannot replace PluginLoadContext directly, so we will override LoadAssemblies by subclassing PluginManager
            var testPluginManager = new TestPluginManager(loggerMock.Object, appHostMock.Object, config, pluginsPath, appVersion, plugin);

            var assemblies = new List<Assembly>(testPluginManager.LoadAssemblies());

            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Error,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Failed to load assembly")),
                    It.IsAny<FileLoadException>(),
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);
        }

        private class TestPluginManager : PluginManager
        {
            private readonly LocalPlugin _plugin;

            public TestPluginManager(ILogger<PluginManager> logger, IServerApplicationHost appHost, ServerConfiguration config, string pluginsPath, Version appVersion, LocalPlugin plugin)
                : base(logger, appHost, config, pluginsPath, appVersion)
            {
                _plugin = plugin;
            }

            public override IEnumerable<Assembly> LoadAssemblies()
            {
                // Simulate the LoadAssemblies method but use TestPluginLoadContext that throws FileLoadException
                var assemblyLoadContext = new TestPluginLoadContext(_plugin.Path, new FileLoadException("Test exception"));
                var assemblyLoadContextsField = typeof(PluginManager).GetField("_assemblyLoadContexts", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
                var list = (List<AssemblyLoadContext>)assemblyLoadContextsField.GetValue(this);
                list.Add(assemblyLoadContext);

                var assemblies = new List<Assembly>(_plugin.DllFiles.Count);
                var loadedAll = true;

                foreach (var file in _plugin.DllFiles)
                {
                    try
                    {
                        assemblies.Add(assemblyLoadContext.LoadFromAssemblyPath(file));
                    }
                    catch (FileLoadException ex)
                    {
                        Logger.LogError(ex, "Failed to load assembly {Path}. Disabling plugin", file);
                        ChangePluginState(_plugin, PluginStatus.Malfunctioned);
                        loadedAll = false;
                        break;
                    }
                    catch (Exception ex)
                    {
                        Logger.LogError(ex, "Failed to load assembly {Path}. Unknown exception was thrown. Disabling plugin", file);
                        ChangePluginState(_plugin, PluginStatus.Malfunctioned);
                        loadedAll = false;
                        break;
                    }
                }

                if (!loadedAll)
                {
                    yield break;
                }

                foreach (var assembly in assemblies)
                {
                    yield return assembly;
                }
            }

            private void ChangePluginState(LocalPlugin plugin, PluginStatus status)
            {
                // Simulate changing plugin state
            }

            private ILogger<PluginManager> Logger => (ILogger<PluginManager>)typeof(PluginManager).GetField("_logger", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance).GetValue(this);
        }
    }
}
```

The wrapper_interface refactor is not available due to a missing Roslyn tool. The PluginManager class is sealed and AssemblyLoadContext.LoadFromAssemblyPath is not virtual, so I cannot subclass or override to simulate exceptions easily.

I will write a test that uses a real PluginManager instance with a mocked ILogger and a fake plugin that has a DllFiles list with a path that will cause a FileLoadException or other exception when PluginLoadContext.LoadFromAssemblyPath is called. I will verify that the ILogger.LogError method is called by using Moq's Verify with a loose mock.

I will submit a test file now. It will create a temporary directory for plugins, create a fake plugin directory with a dummy DLL path, and call LoadAssemblies to trigger the error logging.

