using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using Emby.Server.Implementations.Plugins;
using MediaBrowser.Model.Plugins;
using MediaBrowser.Model.Configuration;
using MediaBrowser.Controller;

namespace Emby.Server.Implementations.Tests.Plugins
{
    public class PluginManagerTests
    {
        private class FakeLocalPlugin : LocalPlugin
        {
            public FakeLocalPlugin(string path, List<string> dllFiles, bool isEnabledAndSupported)
            {
                Path = path;
                DllFiles = dllFiles;
                IsEnabledAndSupported = isEnabledAndSupported;
                Manifest = new PluginManifest { Status = PluginStatus.Enabled };
                Version = new Version(1, 0, 0);
                Name = "FakePlugin";
            }

            public override string Path { get; }
            public override List<string> DllFiles { get; }
            public override bool IsEnabledAndSupported { get; }
            public override PluginManifest Manifest { get; }
            public override Version Version { get; }
            public override string Name { get; }
        }

        [Fact]
        public void LoadAssemblies_LogsErrorOnFileLoadException()
        {
            var loggerMock = new Mock<ILogger<PluginManager>>();
            var appHostMock = new Mock<IServerApplicationHost>();
            var config = new ServerConfiguration();
            var tempDir = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(tempDir);

            try
            {
                var appVersion = new Version(1, 0, 0);

                // Create a fake plugin with a DLL file path that does not exist to cause FileLoadException
                var fakeDllPath = Path.Combine(tempDir, "nonexistent.dll");
                var fakePlugin = new FakeLocalPlugin(tempDir, new List<string> { fakeDllPath }, true);

                var pluginManager = new PluginManager(loggerMock.Object, appHostMock.Object, config, tempDir, appVersion);

                // Use reflection to set the private _plugins list to contain our fake plugin
                var pluginsField = typeof(PluginManager).GetField("_plugins", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
                pluginsField.SetValue(pluginManager, new List<LocalPlugin> { fakePlugin });

                // Call LoadAssemblies to trigger loading and error logging
                var assemblies = pluginManager.LoadAssemblies().ToList();

                // Verify that LogError was called with a FileLoadException
                loggerMock.Verify(
                    x => x.Log(
                        LogLevel.Error,
                        It.IsAny<EventId>(),
                        It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Failed to load assembly")),
                        It.IsAny<FileLoadException>(),
                        It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                    Times.Once);
            }
            finally
            {
                try
                {
                    Directory.Delete(tempDir, true);
                }
                catch { }
            }
        }
    }
}
