                pluginsField.SetValue(pluginManager, list);

                // Call LoadAssemblies to trigger loading and error logging
                var assemblies = pluginManager.LoadAssemblies().ToList();

                // Verify that LogError was called with a message containing "Failed to load assembly"
                loggerMock.Verify(
                    x => x.Log(
                        LogLevel.Error,
                        It.IsAny<EventId>(),
                        It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Failed to load assembly")),
                        It.IsAny<Exception>(),
                        It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                    Times.AtLeastOnce);
            }
            finally
            {
                try
                {
                    Directory.Delete(tempDir, true);
